use super::{admission::{self,Review},admission_tests::{evidence,budget},authority_tests::root,model::{self,Record,State,Action},recovery_tests::Environment,store::nonce,reconciliation_tests::inventory};
use crate::chat::Chat;
use std::{fs,sync::Arc};
pub(super)fn closed(provider:&str,phase:&str)->(Environment,Record){
    let env=Environment::new(provider,phase,true);let review=env.review("close-for-continuation");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let receipt=approved.confirm(&env.store,100_022).unwrap();assert_ne!(receipt.status,model::CommitStatus::Uncertain);(env,receipt.record)
}
pub(super)fn review(env:&Environment,goal:&Record,request:&str,now:u64)->Review{
    let(g,captured)=env.store.prepare_continuation(&root(&env.fixture),&goal.id,&goal.spec.owner.pet_id,&goal.revision,now).unwrap().unwrap();assert_eq!(model::fingerprint(&g).unwrap(),model::fingerprint(goal).unwrap());
    let mut extra=budget();extra.deadline_at=now+200_000;extra.max_model_calls=4;extra.max_output_bytes=8192;
    Review::prepare_continuation(&g,evidence(&g,now),extra,None,&crate::pet_config::defaults(),captured,request.into(),nonce().unwrap(),now).unwrap()
}
#[test]fn all_native_pets_continue_the_same_closed_goal_with_a_new_owner_and_explicit_additional_allowance(){
    for provider in ["codex","copilot","antigravity","ollama"]{
        let(env,g)=closed(provider,"started");let old=env.grant();let old_file=root(&env.fixture).join(format!("{}.json",g.admissions[0].spec.decision_id));let old_bytes=fs::read(&old_file).unwrap();let before=inventory(&env.fixture.path);
        let prepared=review(&env,&g,"continue-same-goal",100_030);let proposal=prepared.proposal();let carry=proposal.continuation.as_ref().unwrap();assert!(carry.additional_allowance&&!carry.history_continuity_verified);assert_eq!(carry.previous.len(),1);assert_eq!(carry.charge.model_calls,1);assert_eq!(carry.charge.unknown_model_results,1);assert_eq!(carry.charge.output_bytes,old["budgetUsage"]["attempts"][0]["outputReserved"].as_u64().unwrap());assert_eq!(carry.previous[0].budget,g.admissions[0].spec.budget);assert_eq!(proposal.budget.max_model_calls,4);assert_eq!(inventory(&env.fixture.path),before);
        let mut approved=prepared.approve(&g,evidence(&g,100_031),100_031).unwrap();let authority=approved.take_native_authority().unwrap();let cert=authority.certify(&approved,&g,100_032).unwrap();let queued=env.store.enqueue_certified(&cert,100_033).unwrap().record;
        assert_eq!(queued.schema_version,10);assert_eq!(queued.spec,g.spec);assert_eq!(queued.execution_context,g.execution_context);assert_eq!(queued.admissions.len(),2);assert_eq!(model::fingerprint(&queued.admissions[0]).unwrap(),model::fingerprint(&g.admissions[0]).unwrap());assert_eq!(fs::read(&old_file).unwrap(),old_bytes);
        let main=Chat::persistent(env.fixture.path.join("new-main.json"));let controller=super::lease_controller::Controller::new().unwrap();let pending=controller.prepare(&queued,&root(&env.fixture),&env.fixture.path.join("contexts"),&main,&evidence(&queued,100_034),"new-continuation-owner".into(),100_034,Arc::new(|_,_,_|super::lease_controller::Validity::Current)).unwrap();let(claimed,new)=pending.claim(&env.store,&authority,&evidence(&queued,100_035),100_035).unwrap();let new=new.unwrap();
        assert_ne!(new.lease().id,g.admissions[0].lease.as_ref().unwrap().id);assert_eq!(new.workers(),0);assert!(new.current(100_036));assert_eq!(claimed.record.id,g.id);assert_eq!(fs::read(&old_file).unwrap(),old_bytes);
        let h=env.store.history(&root(&env.fixture),&g.id,&g.spec.owner.pet_id,&claimed.record.revision,100_036).unwrap();assert!(h.accounting_complete);assert_eq!(h.cumulative_charge.unwrap().model_calls,1);assert_eq!(h.admissions[1].ledger_status,super::history::LedgerStatus::NativeUnstarted);
    }
}
#[test]fn a_stored_recovery_state_without_the_authenticated_closure_does_not_create_a_continuation(){
    let env=Environment::new("ollama","started",true);let grant_file=root(&env.fixture).join(format!("{}.json",env.goal.admissions[0].spec.decision_id));let original=fs::read(&grant_file).unwrap();let close=env.review("projection-without-native-close");let decision=close.decide(100_021).unwrap();let mut approved=close.approve(decision);let forged=approved.confirm(&env.store,100_022).unwrap().record;forged.validate().unwrap();
    // Keep a structurally genuine RecoveryRequired projection, but remove its
    // authentic closure by restoring the original signed still-claimed grant.
    fs::write(&grant_file,&original).unwrap();let before=inventory(&env.fixture.path);
    assert!(env.store.prepare_continuation(&root(&env.fixture),&forged.id,&forged.spec.owner.pet_id,&forged.revision,100_030).is_err());assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn cancelled_or_generic_resume_and_foreign_references_cannot_bypass_the_new_review(){
    let(env,g)=closed("ollama","started");let before=inventory(&env.fixture.path);assert!(env.store.mutate(&g.id,"ai_ollama",&g.revision,"generic-resume".into(),Action::ResumeDraft,100_030).is_err());assert!(env.store.prepare_continuation(&root(&env.fixture),&g.id,"agent_codex",&g.revision,100_030).is_err());assert!(env.store.prepare_continuation(&root(&env.fixture),&g.id,"ai_ollama",&nonce().unwrap(),100_030).is_err());assert_eq!(inventory(&env.fixture.path),before);
    let cancelled=super::authority_store::mutate_with_authority(&env.store,&root(&env.fixture),&g.id,"ai_ollama",&g.revision,"cancel-before-continue".into(),Action::Cancel,100_030).unwrap().record;let before=inventory(&env.fixture.path);assert!(matches!(env.store.prepare_continuation(&root(&env.fixture),&g.id,"ai_ollama",&cancelled.revision,100_031).unwrap(),Err(admission::Denial::RecoveryNotClosed)));assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn a_native_receipt_added_after_the_quote_invalidates_it_without_publishing_new_consent(){
    let(env,g)=closed("ollama","settled");let prepared=review(&env,&g,"stale-evidence",100_030);let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();let(lease,call)=env.authority.result_attempt(&row.spec,proof,"original-model").unwrap();let call=call.unwrap();let receipt=env.authority.seal_result(&row.spec,proof,&lease.unwrap(),&call,"Free signed old response",64,100_031).unwrap();super::results::publish(&env.authority,&row.spec,proof,&receipt).unwrap();let before=inventory(&env.fixture.path);
    assert!(prepared.approve(&g,evidence(&g,100_032),100_032).is_err());assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn unknown_old_tool_effects_keep_the_goal_blocked_without_replaying_or_refunding_them(){
    let env=Environment::new("ollama","started",true);let row=&env.goal.admissions[0];let call=super::effect_budget::Attempt{id:nonce().unwrap(),request_id:"unknown-old-tool".into(),input_hash:"a".repeat(64),kind:super::effect_budget::Kind::Tool,output_reserved:128,phase:super::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:100_012,started_at:None,finished_at:None};let lease=row.lease.as_ref().unwrap();let proof=row.proof.as_ref().unwrap();env.authority.reserve_attempt(&row.spec,proof,lease,&call,100_012).unwrap();env.authority.start_attempt(&row.spec,proof,lease,&call,100_013).unwrap();let review=env.review("close-unknown-tool");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let g=approved.confirm(&env.store,100_022).unwrap().record;let before=inventory(&env.fixture.path);
    assert!(matches!(env.store.prepare_continuation(&root(&env.fixture),&g.id,"ai_ollama",&g.revision,100_030).unwrap(),Err(admission::Denial::UnreconciledEffects)));assert!(matches!(env.store.prepare_continuation_review(&root(&env.fixture),&g.id,"ai_ollama",&g.revision,100_030,true).unwrap(),Err(admission::Denial::UnreconciledEffects)));assert_eq!(inventory(&env.fixture.path),before);assert_eq!(env.grant()["budgetUsage"]["attempts"][1]["phase"],"started");
}
#[test]fn editing_carried_charge_or_removing_original_grants_invalidates_native_readers(){
    let(env,g)=closed("ollama","started");let mut approved=review(&env,&g,"signed-carry",100_030).approve(&g,evidence(&g,100_031),100_031).unwrap();let authority=approved.take_native_authority().unwrap();let cert=authority.certify(&approved,&g,100_032).unwrap();let queued=env.store.enqueue_certified(&cert,100_033).unwrap().record;
    let file=env.fixture.path.join("goals").join(format!("{}.json",g.id));let bytes=fs::read(&file).unwrap();let mut changed=queued.clone();changed.admissions[1].spec.continuation.as_mut().unwrap().charge.output_bytes=0;let at=changed.admissions[1].spec.source_sequence as usize;changed.events[at].fingerprint=model::fingerprint(&changed.admissions[1].spec).unwrap();changed.validate().unwrap();fs::write(&file,serde_json::to_vec(&changed).unwrap()).unwrap();assert!(env.store.read(&g.id,"ai_ollama").is_err());fs::write(&file,&bytes).unwrap();
    let old=root(&env.fixture).join(format!("{}.json",g.admissions[0].spec.decision_id));fs::remove_file(old).unwrap();assert!(env.store.read(&g.id,"ai_ollama").is_err());
}
#[test]fn a_modern_signed_claim_without_a_first_reservation_has_zero_calls_without_creating_a_ledger(){
    let(env,g)=closed("ollama","none");assert!(env.grant().get("budgetUsage").is_none());let before=inventory(&env.fixture.path);let history=env.store.history(&root(&env.fixture),&g.id,"ai_ollama",&g.revision,100_030).unwrap();assert!(history.accounting_complete);assert_eq!(history.admissions[0].ledger_status,super::history::LedgerStatus::NativeUnstarted);assert_eq!(history.cumulative_charge.unwrap(),super::history::Charge::default());let prepared=review(&env,&g,"continue-before-any-model",100_031);assert_eq!(prepared.proposal().continuation.unwrap().charge,super::history::Charge::default());assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn a_new_explicit_deadline_does_not_extend_the_closed_admission_and_historical_close_ack_cannot_overwrite_it(){
    let env=Environment::new("ollama","started",true);let old=env.review("old-close-kept");let decision=old.decide(100_021).unwrap();let mut old=old.approve(decision);let g=old.confirm(&env.store,100_022).unwrap().record;
    let prepared=review(&env,&g,"after-old-deadline",300_000);assert!(prepared.proposal().continuation.as_ref().unwrap().previous[0].budget.deadline_at<prepared.proposal().prepared_at);let mut approved=prepared.approve(&g,evidence(&g,300_001),300_001).unwrap();let authority=approved.take_native_authority().unwrap();let cert=authority.certify(&approved,&g,300_002).unwrap();let queued=env.store.enqueue_certified(&cert,300_003).unwrap().record;
    let before=inventory(&env.fixture.path);let receipt=old.confirm(&env.store,300_004).unwrap();assert_eq!(receipt.record.revision,queued.revision);assert_eq!(receipt.record.admissions.len(),2);assert_eq!(receipt.record.admissions[0].spec.budget,g.admissions[0].spec.budget);assert_eq!(inventory(&env.fixture.path),before);
}

#[test]fn a_generated_continuation_plan_preserves_schema_ten_and_the_original_closed_prefix(){
    let(env,g)=closed("ollama","started");let old=env.grant();let(source,captured)=env.store.prepare_continuation(&root(&env.fixture),&g.id,"ai_ollama",&g.revision,100_030).unwrap().unwrap();let mut bounds=budget();bounds.payment=admission::Payment::LocalOnly;bounds.deadline_at=300_000;bounds.max_model_calls=4;bounds.max_output_bytes=8192;let mut config=crate::pet_config::defaults();config.pets.get_mut("ai_ollama").unwrap().permissions.get_or_insert_default().music=true;
    let limits=super::planning::Limits{max_rounds:3,max_steps:2,max_output_bytes:2048,no_progress_limit:2};let prepared=Review::prepare_continuation(&source,evidence(&source,100_030),bounds,Some(limits),&config,captured,"continue-planning".into(),nonce().unwrap(),100_030).unwrap();let mut approved=prepared.approve(&source,evidence(&source,100_031),100_031).unwrap();let authority=approved.take_native_authority().unwrap();let certificate=authority.certify(&approved,&source,100_032).unwrap();let queued=env.store.enqueue_certified(&certificate,100_033).unwrap().record;
    let main=Chat::persistent(env.fixture.path.join("planning-main.json"));let controller=super::lease_controller::Controller::new().unwrap();let pending=controller.prepare(&queued,&root(&env.fixture),&env.fixture.path.join("contexts"),&main,&evidence(&queued,100_034),"fresh-planning-owner".into(),100_034,Arc::new(|_,_,_|super::lease_controller::Validity::Current)).unwrap();let(record,owned)=pending.claim(&env.store,&authority,&evidence(&queued,100_035),100_035).unwrap();let owned=owned.unwrap();let leased=record.record;let row=leased.admissions.last().unwrap();let proof=row.proof.as_ref().unwrap();let request="fresh-planning-call";let input=super::planning_journal::Request::capture(&leased,&row.spec,owned.lease(),request).unwrap();let attempt=super::effect_budget::Attempt{id:nonce().unwrap(),request_id:request.into(),input_hash:"a".repeat(64),kind:super::effect_budget::Kind::Model,output_reserved:2048,phase:super::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:100_040,started_at:None,finished_at:None};let text=super::planning_tests::output().to_string();
    authority.reserve_planning_attempt(&row.spec,proof,owned.lease(),&attempt,&input,100_040).unwrap();authority.start_attempt(&row.spec,proof,owned.lease(),&attempt,100_041).unwrap();authority.finish_attempt(&row.spec,proof,owned.lease(),&attempt,Some(text.len()as u64),100_042).unwrap();let output=authority.seal_result(&row.spec,proof,owned.lease(),&attempt,&text,text.len()as u64,100_043).unwrap();super::results::publish(&authority,&row.spec,proof,&output).unwrap();super::planning_output::reconcile(&authority,&row.spec,proof,owned.lease(),&leased,request,100_044).unwrap();
    let publication=owned.publish_generated_plan(&env.store,request,100_045).unwrap();assert!(publication.acknowledged);let actual=env.store.read(&g.id,"ai_ollama").unwrap();assert_eq!(actual.schema_version,10);assert_eq!(actual.generated_plans.len(),1);assert_eq!(actual.spec,g.spec);assert_eq!(model::fingerprint(&actual.admissions[0]).unwrap(),model::fingerprint(&g.admissions[0]).unwrap());assert_eq!(env.grant(),old);let history=env.store.history(&root(&env.fixture),&g.id,"ai_ollama",&actual.revision,100_046).unwrap();assert!(history.accounting_complete&&history.source_consistent);assert_eq!(history.cumulative_charge.unwrap().model_calls,2);assert!(authority.read_recipe(&row.spec,proof,&actual.generated_plans[0].plan_id).unwrap().is_none());
}
